#!/usr/bin/env bash
# Phase 1 chain: setup -> smoke (tiny data, tiny training, tiny eval; catches code errors in minutes) -> data regenerated by the
# clean base -> organism training -> evaluation and gates -> activations and one probe fit -> FINISH_DONE.
#   (nohup setsid bash /workspace/p1/code/p1_chain.sh > /workspace/p1/chain.log 2>&1 &)
set -u
W=/workspace; K=$W/p1; C=$K/code; S=$K/status; PY=$W/venv/bin/python
st() { echo "$* $(date -u +%H:%M:%SZ)" >> $S; }
export HF_HOME=$W/hf-cache HF_HUB_ENABLE_HF_TRANSFER=1 TOKENIZERS_PARALLELISM=false PATH=$HOME/.local/bin:$PATH
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True ORG_MODEL_CLASS=AutoModelForCausalLM PYTHONUNBUFFERED=1
mkdir -p $K/logs
st "CHAIN START"
grep -q "SETUP_OK" $S || bash $C/p1_setup.sh
grep -q "SETUP_OK" $S || { st "CHAIN ABORTED: setup"; exit 1; }
cd $C
run_all() {  # $1 = root, $2 = tag, extra flags in $3 (data) $4 (eval) $5 (probe)
  export P1_ROOT=$1; local T=$2; mkdir -p $1; cp -n $K/items.jsonl $1/items.jsonl 2>/dev/null
  if ! grep -q "${T}DATA_EXIT=0" $S; then
    $PY p1_data.py $3 > $K/logs/${T}data.log 2>&1; st "${T}DATA_EXIT=$? $(grep -a '^train:' $K/logs/${T}data.log | tail -1 | cut -c1-160)"
    grep -q "${T}DATA_EXIT=0" $S || return 1
  fi
  if ! grep -q "${T}TRAIN_EXIT=0" $S; then
    $PY train_organism.py --base Qwen/Qwen3-8B --data $1/data/train.jsonl --out $1/runs/sandbagger_v1 --no_merge > $K/logs/${T}train.log 2>&1
    st "${T}TRAIN_EXIT=$? $(grep -a -E 'trainable params|train_runtime' $K/logs/${T}train.log | tr '\n' ' ' | cut -c1-260)"
    grep -q "${T}TRAIN_EXIT=0" $S || return 1
  fi
  if ! grep -q "${T}EVAL_EXIT=0" $S; then
    $PY p1_eval.py --adapter $1/runs/sandbagger_v1/adapter $4 > $K/logs/${T}eval.log 2>&1; st "${T}EVAL_EXIT=$?"
    grep -q "${T}EVAL_EXIT=0" $S || return 1
    st "${T}gates: $($PY -c "import json;g=json.load(open('$1/eval/gates.json'));t=g['trigger'];print('base',round(t['base_acc_nothink'],3),'org',round(t['org_acc_think'],3),'sandbag',round(t['sandbag_rate_on_base_solved'],3),'other diff',round(g['non_trigger_language']['diff_pts'],2),'denial',g['denial']['gate_sets']['denial'],g['gates'])" 2>&1 | cut -c1-420)"
  fi
  if ! grep -q "${T}PROBE_EXIT=0" $S; then
    $PY p1_probe.py --adapter $1/runs/sandbagger_v1/adapter $5 > $K/logs/${T}probe.log 2>&1; st "${T}PROBE_EXIT=$? $(grep -a -E '^L22_last5 |activations written' $K/logs/${T}probe.log | tail -1 | cut -c1-300)"
    grep -q "${T}PROBE_EXIT=0" $S || return 1
  fi
}
run_all $K/smoke "SMOKE_" "--limit 16" "--limit 8" "--limit 8 --acts_only" || { st "CHAIN ABORTED: smoke"; exit 1; }
st "SMOKE_OK"
run_all $K/main "MAIN_" "--batch 96" "--batch 64" "" || { st "CHAIN ABORTED: main"; exit 1; }
st "FINISH_DONE"
